CREATE OR REPLACE FUNCTION public.check_reservation_available(p_product_id uuid, p_reserved_date date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_has_reservation BOOLEAN;
  v_has_hold BOOLEAN;
  v_hold_by_self BOOLEAN;
BEGIN
  -- 만료된 홀드 정리
  DELETE FROM reservation_holds WHERE expires_at < now();

  -- 1. 예약이 있는지 확인
  SELECT EXISTS (
    SELECT 1 FROM reservations
    WHERE product_id = p_product_id
      AND reserved_date = p_reserved_date
      AND status IN ('pending', 'paid', 'confirmed')
  ) INTO v_has_reservation;

  IF v_has_reservation THEN
    RETURN json_build_object(
      'available', false,
      'reason', 'already_reserved',
      'message', '해당 날짜에 이미 예약이 있습니다.'
    );
  END IF;

  -- 2. 다른 사용자의 홀드가 있는지 확인
  SELECT 
    EXISTS (
      SELECT 1 FROM reservation_holds
      WHERE product_id = p_product_id
        AND reserved_date = p_reserved_date
        AND expires_at > now()
    ),
    EXISTS (
      SELECT 1 FROM reservation_holds
      WHERE product_id = p_product_id
        AND reserved_date = p_reserved_date
        AND expires_at > now()
        AND daycare_id = auth.uid()
    )
  INTO v_has_hold, v_hold_by_self;

  IF v_has_hold AND NOT v_hold_by_self THEN
    RETURN json_build_object(
      'available', false,
      'reason', 'hold_by_other',
      'message', '다른 사용자가 결제를 진행 중입니다.'
    );
  END IF;

  RETURN json_build_object(
    'available', true,
    'reason', null,
    'message', null
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.renew_expiring_product_booking_windows()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today date := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')::date;
  v_updated_count integer;
BEGIN
  UPDATE public.products
  SET booking_start_date = v_today,
      booking_end_date = (v_today + INTERVAL '1 year')::date,
      updated_at = now()
  WHERE booking_end_date IS NULL
     OR booking_end_date <= v_today + 30;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  RETURN v_updated_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.change_admin_password(p_current_password text, p_new_password text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_admin public.admins%ROWTYPE;
  v_current_hash text;
  v_new_hash text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  SELECT *
  INTO v_admin
  FROM public.admins
  WHERE id = auth.uid()
    AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ADMIN_NOT_FOUND';
  END IF;

  v_current_hash := encode(
    extensions.digest(p_current_password || 'damda-salt-2024', 'sha256'),
    'hex'
  );

  IF v_current_hash <> v_admin.password_hash THEN
    RAISE EXCEPTION 'CURRENT_PASSWORD_INVALID';
  END IF;

  IF p_new_password = p_current_password THEN
    RAISE EXCEPTION 'PASSWORD_REUSE_NOT_ALLOWED';
  END IF;

  IF length(p_new_password) < 8
    OR p_new_password !~ '[A-Za-z]'
    OR p_new_password !~ '[0-9]'
    OR p_new_password !~ '[^A-Za-z0-9]'
  THEN
    RAISE EXCEPTION 'PASSWORD_POLICY_VIOLATION';
  END IF;

  v_new_hash := encode(
    extensions.digest(p_new_password || 'damda-salt-2024', 'sha256'),
    'hex'
  );

  UPDATE public.admins
  SET password_hash = v_new_hash,
      updated_at = now()
  WHERE id = v_admin.id;

  INSERT INTO public.admin_logs (
    admin_id,
    action,
    target_type,
    target_id,
    before_data,
    after_data
  ) VALUES (
    v_admin.id,
    'update',
    'admin',
    v_admin.id,
    jsonb_build_object('password_changed', false),
    jsonb_build_object('password_changed', true)
  );

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_partner_onboarding(p_onboarding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_onboarding public.partner_onboardings%ROWTYPE;
  v_signup public.business_owner_signup_requests%ROWTYPE;
  v_owner_id uuid := gen_random_uuid();
  v_product record;
  v_product_id uuid;
  v_image text;
  v_option jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.admins WHERE id = auth.uid()) THEN
    RAISE EXCEPTION '관리자만 입점을 승인할 수 있습니다.';
  END IF;

  SELECT * INTO v_onboarding
  FROM public.partner_onboardings
  WHERE id = p_onboarding_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION '입점 신청을 찾을 수 없습니다.'; END IF;
  IF v_onboarding.status = 'approved' THEN
    RETURN jsonb_build_object('success', true, 'business_owner_id', v_onboarding.business_owner_id);
  END IF;
  IF v_onboarding.status <> 'ready_for_approval' THEN RAISE EXCEPTION '승인 대기 상태가 아닙니다.'; END IF;
  IF v_onboarding.contract_status <> 'completed' THEN RAISE EXCEPTION '계약이 완료되지 않았습니다.'; END IF;
  IF v_onboarding.signup_request_id IS NULL THEN RAISE EXCEPTION '사업주 콘솔 가입 계정이 연결되지 않았습니다.'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.partner_onboarding_documents
    WHERE onboarding_id = p_onboarding_id AND document_type = 'business_registration'
  ) OR NOT EXISTS (
    SELECT 1 FROM public.partner_onboarding_documents
    WHERE onboarding_id = p_onboarding_id AND document_type = 'bank_account'
  ) THEN RAISE EXCEPTION '필수 서류가 누락되었습니다.'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_onboarding_products WHERE onboarding_id = p_onboarding_id) THEN
    RAISE EXCEPTION '등록할 상품이 없습니다.';
  END IF;
  IF (SELECT count(*) FROM public.partner_onboarding_products WHERE onboarding_id = p_onboarding_id) > 10 THEN
    RAISE EXCEPTION '사업주별 상품은 최대 10개까지 등록할 수 있습니다.';
  END IF;

  SELECT * INTO v_signup
  FROM public.business_owner_signup_requests
  WHERE id = v_onboarding.signup_request_id
  FOR UPDATE;

  IF NOT FOUND OR v_signup.status <> 'pending' THEN RAISE EXCEPTION '유효한 가입 신청이 아닙니다.'; END IF;
  IF regexp_replace(v_signup.business_number, '[^0-9]', '', 'g') <> v_onboarding.business_number THEN
    RAISE EXCEPTION '가입 신청과 입점 신청의 사업자번호가 일치하지 않습니다.';
  END IF;
  IF lower(btrim(v_signup.email)) <> lower(btrim(v_onboarding.email)) THEN
    RAISE EXCEPTION '가입 신청과 입점 신청의 이메일이 일치하지 않습니다.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.business_owners WHERE business_number = v_onboarding.business_number) THEN
    RAISE EXCEPTION '이미 등록된 사업자번호입니다.';
  END IF;

  UPDATE public.partner_onboardings SET status = 'approving', updated_at = now()
  WHERE id = p_onboarding_id;

  INSERT INTO public.business_owners (
    id, auth_user_id, owner_code, email, name, business_number, representative,
    contact_name, contact_phone, address, address_detail, zipcode,
    bank_name, bank_account, bank_holder, tax_email, commission_rate, status
  ) VALUES (
    v_owner_id, v_signup.auth_user_id, v_onboarding.owner_code, v_signup.email, v_onboarding.business_name,
    v_onboarding.business_number, v_onboarding.representative, v_onboarding.contact_name,
    v_onboarding.contact_phone, v_onboarding.address, v_onboarding.address_detail,
    v_onboarding.zipcode, v_onboarding.bank_name, v_onboarding.bank_account,
    v_onboarding.bank_holder, v_onboarding.tax_email, v_onboarding.commission_rate, 'active'
  );

  INSERT INTO public.business_owner_documents (
    business_owner_id, document_type, file_name, file_url, file_size, mime_type,
    storage_bucket, storage_path, sort_order
  )
  SELECT v_owner_id, document_type, file_name, storage_path, file_size, mime_type,
         'partner-onboarding-documents', storage_path,
         CASE WHEN document_type = 'business_registration' THEN 0 ELSE 1 END
  FROM public.partner_onboarding_documents WHERE onboarding_id = p_onboarding_id;

  FOR v_product IN
    SELECT * FROM public.partner_onboarding_products
    WHERE onboarding_id = p_onboarding_id ORDER BY sort_order, created_at
  LOOP
    INSERT INTO public.products (
      business_owner_id, category_id, name, summary, description, thumbnail,
      original_price, sale_price, min_participants, max_participants,
      duration_minutes, address, address_detail, region, is_visible
    ) VALUES (
      v_owner_id, v_product.category_id, v_product.name, v_product.summary,
      v_product.description, v_product.thumbnail, v_product.original_price,
      v_product.sale_price, v_product.min_participants, v_product.max_participants,
      v_product.duration_minutes, v_product.address, v_product.address_detail,
      v_product.region, false
    ) RETURNING id INTO v_product_id;

    FOR v_image IN SELECT jsonb_array_elements_text(v_product.image_urls)
    LOOP
      INSERT INTO public.product_images (product_id, image_url, sort_order)
      VALUES (v_product_id, v_image, 0);
    END LOOP;
    FOR v_option IN SELECT value FROM jsonb_array_elements(v_product.options)
    LOOP
      INSERT INTO public.product_options (product_id, name, price, is_required, sort_order)
      VALUES (
        v_product_id,
        v_option->>'name',
        COALESCE((v_option->>'price')::integer, 0),
        COALESCE((v_option->>'is_required')::boolean, false),
        COALESCE((v_option->>'sort_order')::integer, 0)
      );
    END LOOP;
  END LOOP;

  INSERT INTO public.user_roles (id, role) VALUES (v_signup.auth_user_id, 'business_owner')
  ON CONFLICT (id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.business_owner_signup_requests
  SET status = 'approved', matched_business_owner_id = v_owner_id,
      reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
  WHERE id = v_signup.id;

  UPDATE public.partner_onboardings
  SET status = 'approved', business_owner_id = v_owner_id,
      approved_by = auth.uid(), approved_at = now(), updated_at = now()
  WHERE id = p_onboarding_id;

  RETURN jsonb_build_object('success', true, 'business_owner_id', v_owner_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_business_owner_safely(p_business_owner_id uuid, p_confirmation_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner public.business_owners%ROWTYPE;
  v_product_count integer;
  v_reservation_count integer;
  v_settlement_count integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admins
    WHERE id = auth.uid() AND is_active = true
  ) THEN
    RAISE EXCEPTION 'ADMIN_REQUIRED';
  END IF;

  SELECT * INTO v_owner
  FROM public.business_owners
  WHERE id = p_business_owner_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BUSINESS_OWNER_NOT_FOUND';
  END IF;
  IF btrim(COALESCE(p_confirmation_name, '')) <> v_owner.name THEN
    RAISE EXCEPTION 'CONFIRMATION_NAME_MISMATCH';
  END IF;

  SELECT count(*) INTO v_product_count FROM public.products
  WHERE business_owner_id = p_business_owner_id;
  SELECT count(*) INTO v_reservation_count FROM public.reservations
  WHERE business_owner_id = p_business_owner_id;
  SELECT count(*) INTO v_settlement_count FROM public.settlements
  WHERE business_owner_id = p_business_owner_id;

  IF v_product_count > 0 OR v_reservation_count > 0 OR v_settlement_count > 0 THEN
    RAISE EXCEPTION 'BUSINESS_OWNER_HAS_RELATED_DATA products=% reservations=% settlements=%',
      v_product_count, v_reservation_count, v_settlement_count;
  END IF;

  IF v_owner.auth_user_id IS NOT NULL THEN
    DELETE FROM public.user_roles
    WHERE id = v_owner.auth_user_id AND role = 'business_owner';
  END IF;

  DELETE FROM public.business_owners WHERE id = p_business_owner_id;

  RETURN jsonb_build_object(
    'success', true,
    'business_owner_id', p_business_owner_id,
    'name', v_owner.name
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_business_safely(p_business_id uuid, p_confirmation_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_business public.businesses%ROWTYPE; v_products integer; v_reservations integer;
BEGIN
  SELECT * INTO v_business FROM public.businesses WHERE id = p_business_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'BUSINESS_NOT_FOUND'; END IF;
  IF NOT (v_business.business_owner_id = public.current_business_owner_id()
          OR EXISTS (SELECT 1 FROM public.admins WHERE id = auth.uid() AND is_active = true)) THEN
    RAISE EXCEPTION 'BUSINESS_ACCESS_DENIED';
  END IF;
  IF btrim(COALESCE(p_confirmation_name, '')) <> v_business.name THEN
    RAISE EXCEPTION 'CONFIRMATION_NAME_MISMATCH';
  END IF;
  SELECT count(*) INTO v_products FROM public.products WHERE business_id = p_business_id;
  SELECT count(*) INTO v_reservations FROM public.reservations WHERE business_id = p_business_id;
  IF v_products > 0 OR v_reservations > 0 OR v_business.is_primary THEN
    RAISE EXCEPTION 'BUSINESS_HAS_RELATED_DATA_OR_IS_PRIMARY products=% reservations=%', v_products, v_reservations;
  END IF;
  DELETE FROM public.businesses WHERE id = p_business_id;
  RETURN jsonb_build_object('success', true, 'business_id', p_business_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.prepare_generated_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reservation public.reservations%ROWTYPE;
BEGIN
  IF NEW.document_number IS NULL OR btrim(NEW.document_number) = '' THEN
    NEW.document_number := public.next_generated_document_number(NEW.document_type);
  END IF;

  IF NEW.reservation_id IS NOT NULL THEN
    SELECT * INTO v_reservation FROM public.reservations WHERE id = NEW.reservation_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'DOCUMENT_RESERVATION_NOT_FOUND'; END IF;
    IF auth.uid() IS NOT NULL AND v_reservation.daycare_id <> auth.uid()
       AND NOT EXISTS (SELECT 1 FROM public.admins WHERE id = auth.uid() AND is_active = true) THEN
      RAISE EXCEPTION 'DOCUMENT_RESERVATION_ACCESS_DENIED';
    END IF;
    NEW.daycare_id := v_reservation.daycare_id;
    NEW.business_owner_id := v_reservation.business_owner_id;
    NEW.business_id := v_reservation.business_id;
  ELSIF auth.uid() IS NOT NULL
        AND NEW.daycare_id <> auth.uid()
        AND NOT EXISTS (SELECT 1 FROM public.admins WHERE id = auth.uid() AND is_active = true) THEN
    RAISE EXCEPTION 'DOCUMENT_DAYCARE_ACCESS_DENIED';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'issued' THEN
    IF NEW.reservation_snapshot IS DISTINCT FROM OLD.reservation_snapshot
       OR NEW.publisher_snapshot IS DISTINCT FROM OLD.publisher_snapshot
       OR NEW.editable_content IS DISTINCT FROM OLD.editable_content THEN
      RAISE EXCEPTION 'ISSUED_DOCUMENT_IS_IMMUTABLE';
    END IF;
  END IF;

  IF NEW.status = 'issued' AND NEW.issued_at IS NULL THEN NEW.issued_at := now(); END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_business_owner_signup(p_request_id uuid, p_business_owner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.business_owner_signup_requests%ROWTYPE;
  v_owner public.business_owners%ROWTYPE;
  v_previous_auth_user_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admins
    WHERE id = auth.uid() AND is_active = true
  ) THEN
    RAISE EXCEPTION 'ADMIN_REQUIRED';
  END IF;

  SELECT * INTO v_request
  FROM public.business_owner_signup_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BUSINESS_SIGNUP_REQUEST_NOT_FOUND';
  END IF;
  IF v_request.status NOT IN ('pending', 'on_hold', 'rejected') THEN
    RAISE EXCEPTION 'BUSINESS_SIGNUP_REQUEST_ALREADY_PROCESSED';
  END IF;

  SELECT * INTO v_owner
  FROM public.business_owners
  WHERE id = p_business_owner_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BUSINESS_OWNER_NOT_FOUND';
  END IF;
  IF lower(btrim(v_request.email)) <> lower(btrim(v_owner.email)) THEN
    RAISE EXCEPTION 'BUSINESS_OWNER_EMAIL_MISMATCH';
  END IF;

  v_previous_auth_user_id := v_owner.auth_user_id;

  UPDATE public.business_owners
  SET auth_user_id = v_request.auth_user_id,
      bank_name = COALESCE(NULLIF(btrim(v_request.bank_name), ''), bank_name),
      bank_holder = COALESCE(NULLIF(btrim(v_request.bank_holder), ''), bank_holder),
      bank_account = COALESCE(NULLIF(v_request.bank_account, ''), bank_account),
      status = 'active',
      updated_at = now()
  WHERE id = p_business_owner_id;

  IF v_request.business_registration_storage_path IS NOT NULL THEN
    DELETE FROM public.business_owner_documents
    WHERE business_owner_id = p_business_owner_id AND document_type = 'business_registration';

    INSERT INTO public.business_owner_documents (
      business_owner_id, document_type, file_name, file_url, file_size, mime_type,
      storage_bucket, storage_path, sort_order
    ) VALUES (
      p_business_owner_id,
      'business_registration',
      COALESCE(v_request.business_registration_file_name, '사업자등록증'),
      v_request.business_registration_storage_path,
      v_request.business_registration_file_size,
      v_request.business_registration_mime_type,
      COALESCE(v_request.business_registration_storage_bucket, 'business-signup-documents'),
      v_request.business_registration_storage_path,
      0
    );
  END IF;

  IF v_request.bank_account_copy_storage_path IS NOT NULL THEN
    DELETE FROM public.business_owner_documents
    WHERE business_owner_id = p_business_owner_id AND document_type = 'bank_account';

    INSERT INTO public.business_owner_documents (
      business_owner_id, document_type, file_name, file_url, file_size, mime_type,
      storage_bucket, storage_path, sort_order
    ) VALUES (
      p_business_owner_id,
      'bank_account',
      COALESCE(v_request.bank_account_copy_file_name, '통장사본'),
      v_request.bank_account_copy_storage_path,
      v_request.bank_account_copy_file_size,
      v_request.bank_account_copy_mime_type,
      COALESCE(v_request.bank_account_copy_storage_bucket, 'business-signup-documents'),
      v_request.bank_account_copy_storage_path,
      1
    );
  END IF;

  IF v_previous_auth_user_id IS NOT NULL
     AND v_previous_auth_user_id <> v_request.auth_user_id THEN
    DELETE FROM public.user_roles
    WHERE id = v_previous_auth_user_id AND role = 'business_owner';
  END IF;

  INSERT INTO public.user_roles (id, role)
  VALUES (v_request.auth_user_id, 'business_owner')
  ON CONFLICT (id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.business_owner_signup_requests
  SET status = 'approved',
      matched_business_owner_id = p_business_owner_id,
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      updated_at = now()
  WHERE id = p_request_id;

  RETURN jsonb_build_object(
    'success', true,
    'business_owner_id', p_business_owner_id,
    'auth_user_id', v_request.auth_user_id,
    'owner_code', v_owner.owner_code,
    'email', v_owner.email
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.review_business_owner_signup(p_request_id uuid, p_status text, p_review_note text DEFAULT NULL::text, p_business_owner_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.business_owner_signup_requests%ROWTYPE;
  v_business_owner_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admins
    WHERE id = auth.uid() AND is_active = true
  ) THEN
    RAISE EXCEPTION 'ADMIN_REQUIRED';
  END IF;

  SELECT * INTO v_request
  FROM public.business_owner_signup_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BUSINESS_SIGNUP_REQUEST_NOT_FOUND';
  END IF;

  IF p_status = 'approved' THEN
    IF v_request.status = 'approved' THEN
      UPDATE public.business_owner_signup_requests
      SET review_note = NULLIF(btrim(p_review_note), ''),
          reviewed_by = auth.uid(),
          reviewed_at = now(),
          updated_at = now()
      WHERE id = p_request_id;
      RETURN jsonb_build_object('success', true, 'status', 'approved');
    END IF;

    v_business_owner_id := COALESCE(
      v_request.matched_business_owner_id,
      p_business_owner_id
    );

    IF v_business_owner_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.business_owners
         WHERE id = v_business_owner_id
       ) THEN
      IF v_business_owner_id <> v_request.auth_user_id THEN
        RAISE EXCEPTION 'BUSINESS_OWNER_NOT_FOUND';
      END IF;
      v_business_owner_id := NULL;
    END IF;

    IF v_business_owner_id IS NULL THEN
      SELECT id INTO v_business_owner_id
      FROM public.business_owners
      WHERE auth_user_id = v_request.auth_user_id
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF v_business_owner_id IS NULL THEN
      IF EXISTS (
        SELECT 1 FROM public.business_owners
        WHERE lower(btrim(email)) = lower(btrim(v_request.email))
           OR business_number = v_request.business_number
      ) THEN
        RAISE EXCEPTION 'BUSINESS_OWNER_SIGNUP_CONFLICT';
      END IF;

      INSERT INTO public.business_owners (
        id,
        auth_user_id,
        email,
        name,
        business_number,
        representative,
        contact_name,
        contact_phone,
        address,
        bank_name,
        bank_holder,
        bank_account,
        status
      ) VALUES (
        v_request.auth_user_id,
        v_request.auth_user_id,
        lower(btrim(v_request.email)),
        btrim(v_request.business_name),
        v_request.business_number,
        btrim(v_request.representative),
        btrim(v_request.contact_name),
        v_request.contact_phone,
        '',
        NULLIF(btrim(v_request.bank_name), ''),
        NULLIF(btrim(v_request.bank_holder), ''),
        NULLIF(v_request.bank_account, ''),
        'active'
      )
      RETURNING id INTO v_business_owner_id;
    END IF;

    PERFORM public.approve_business_owner_signup(
      p_request_id,
      v_business_owner_id
    );

    UPDATE public.business_owner_signup_requests
    SET review_note = NULLIF(btrim(p_review_note), ''),
        updated_at = now()
    WHERE id = p_request_id;

    RETURN jsonb_build_object(
      'success', true,
      'status', 'approved',
      'business_owner_id', v_business_owner_id
    );
  END IF;

  IF p_status NOT IN ('rejected', 'on_hold') THEN
    RAISE EXCEPTION 'INVALID_BUSINESS_SIGNUP_STATUS';
  END IF;

  IF v_request.status = 'approved'
     AND v_request.matched_business_owner_id IS NOT NULL THEN
    UPDATE public.business_owners
    SET status = 'inactive', updated_at = now()
    WHERE id = v_request.matched_business_owner_id;
  END IF;

  UPDATE public.business_owner_signup_requests
  SET status = p_status,
      review_note = NULLIF(btrim(p_review_note), ''),
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      updated_at = now()
  WHERE id = p_request_id;

  RETURN jsonb_build_object('success', true, 'status', p_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_sensitive_profile_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  IF public.is_active_admin() OR auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'daycares' THEN
    IF NEW.id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION 'Only the applicant can edit this profile' USING ERRCODE='42501';
    END IF;
    IF TG_OP = 'INSERT' THEN
      IF NEW.status IS DISTINCT FROM 'pending' OR NEW.approved_at IS NOT NULL
        OR NEW.rejection_reason IS NOT NULL OR NEW.revision_reason IS NOT NULL
        OR NEW.revision_requested_at IS NOT NULL OR NEW.deleted_at IS NOT NULL OR NEW.deleted_by IS NOT NULL THEN
        RAISE EXCEPTION 'Only an administrator can approve an application' USING ERRCODE='42501';
      END IF;
    ELSE
      IF NEW.id IS DISTINCT FROM OLD.id OR NEW.email IS DISTINCT FROM OLD.email
        OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
        OR NEW.rejection_reason IS DISTINCT FROM OLD.rejection_reason
        OR NEW.revision_reason IS DISTINCT FROM OLD.revision_reason
        OR NEW.revision_requested_at IS DISTINCT FROM OLD.revision_requested_at
        OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at OR NEW.deleted_by IS DISTINCT FROM OLD.deleted_by
        OR (NEW.status IS DISTINCT FROM OLD.status AND NOT (
          OLD.status = 'revision_required' AND NEW.status = 'requested'
          AND NEW.revision_submitted_at IS NOT NULL
        )) THEN
        RAISE EXCEPTION 'Only an administrator can change approval information' USING ERRCODE='42501';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'business_owners' THEN
    IF NEW.commission_rate IS DISTINCT FROM OLD.commission_rate
      OR NEW.status IS DISTINCT FROM OLD.status
      OR NEW.business_number IS DISTINCT FROM OLD.business_number
      OR NEW.email IS DISTINCT FROM OLD.email THEN
      RAISE EXCEPTION 'Only an administrator can change business privileges' USING ERRCODE='42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_admin_product_preview_token(p_product_id uuid)
 RETURNS TABLE(token uuid, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_business_owner_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.admins
    WHERE id = auth.uid() AND is_active = true
  ) THEN
    RAISE EXCEPTION 'ADMIN_REQUIRED';
  END IF;

  SELECT p.business_owner_id
  INTO v_business_owner_id
  FROM public.products p
  WHERE p.id = p_product_id;

  IF v_business_owner_id IS NULL THEN
    RAISE EXCEPTION 'PRODUCT_NOT_FOUND';
  END IF;

  DELETE FROM public.product_preview_tokens ppt
  WHERE ppt.product_id = p_product_id
    AND ppt.expires_at <= now();

  RETURN QUERY
  INSERT INTO public.product_preview_tokens(product_id, business_owner_id)
  VALUES (p_product_id, v_business_owner_id)
  RETURNING product_preview_tokens.token, product_preview_tokens.expires_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_secure_payment_order(p_items jsonb, p_reserver_info jsonb, p_payment_method text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_daycare_id uuid := auth.uid();
  v_item jsonb;
  v_option_input jsonb;
  v_product public.products%ROWTYPE;
  v_option public.product_options%ROWTYPE;
  v_product_id uuid;
  v_reserved_date date;
  v_participants integer;
  v_quantity integer;
  v_item_total integer;
  v_total integer := 0;
  v_snapshot jsonb := '[]'::jsonb;
  v_options jsonb;
  v_order_id text;
  v_goods_name text;
  v_item_count integer := 0;
BEGIN
  IF v_daycare_id IS NULL OR NOT public.is_daycare() THEN
    RAISE EXCEPTION '승인된 보육기관 회원만 결제할 수 있습니다.';
  END IF;
  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 OR jsonb_array_length(p_items) > 20 THEN
    RAISE EXCEPTION '주문 상품 정보가 올바르지 않습니다.';
  END IF;
  IF p_payment_method NOT IN ('card', 'bank') THEN
    RAISE EXCEPTION '결제수단이 올바르지 않습니다.';
  END IF;
  IF NULLIF(trim(COALESCE(p_reserver_info ->> 'name', '')), '') IS NULL
     OR NULLIF(trim(COALESCE(p_reserver_info ->> 'phone', '')), '') IS NULL THEN
    RAISE EXCEPTION '예약자 정보가 올바르지 않습니다.';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := NULLIF(v_item ->> 'productId', '')::uuid;
    v_reserved_date := NULLIF(v_item ->> 'reservedDate', '')::date;
    v_participants := (v_item ->> 'participants')::integer;
    IF v_product_id IS NULL OR v_reserved_date IS NULL OR v_participants IS NULL OR v_participants < 1 THEN
      RAISE EXCEPTION '상품 또는 예약 인원 정보가 올바르지 않습니다.';
    END IF;
    SELECT * INTO v_product FROM public.products WHERE id = v_product_id FOR SHARE;
    IF NOT FOUND OR NOT v_product.is_visible OR v_product.is_sold_out THEN
      RAISE EXCEPTION '예약할 수 없는 상품입니다.';
    END IF;
    IF v_reserved_date < CURRENT_DATE OR v_participants < v_product.min_participants OR v_participants > v_product.max_participants THEN
      RAISE EXCEPTION '예약 날짜 또는 인원이 상품 조건에 맞지 않습니다.';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.product_unavailable_dates u
      WHERE u.product_id = v_product_id AND u.unavailable_date = v_reserved_date
    ) THEN
      RAISE EXCEPTION '선택한 날짜는 예약할 수 없습니다.';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.reservation_holds h
      WHERE h.product_id = v_product_id
        AND h.reserved_date = v_reserved_date
        AND h.daycare_id = v_daycare_id
        AND h.expires_at > now()
    ) THEN
      RAISE EXCEPTION '결제 대기 시간이 만료되었습니다. 다시 시도해주세요.';
    END IF;

    v_item_total := v_product.sale_price * v_participants;
    v_options := '[]'::jsonb;
    FOR v_option_input IN SELECT value FROM jsonb_array_elements(COALESCE(v_item -> 'options', '[]'::jsonb))
    LOOP
      v_quantity := (v_option_input ->> 'quantity')::integer;
      IF v_quantity IS NULL OR v_quantity < 1 OR v_quantity > 100 THEN
        RAISE EXCEPTION '옵션 수량이 올바르지 않습니다.';
      END IF;
      SELECT * INTO v_option FROM public.product_options
      WHERE id = NULLIF(v_option_input ->> 'id', '')::uuid AND product_id = v_product_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION '상품 옵션 정보가 올바르지 않습니다.';
      END IF;
      v_item_total := v_item_total + (v_option.price * v_quantity);
      v_options := v_options || jsonb_build_array(jsonb_build_object(
        'id', v_option.id, 'name', v_option.name, 'price', v_option.price, 'quantity', v_quantity
      ));
    END LOOP;

    v_snapshot := v_snapshot || jsonb_build_array(jsonb_build_object(
      'productId', v_product.id,
      'productName', v_product.name,
      'businessOwnerId', v_product.business_owner_id,
      'reservedDate', v_reserved_date,
      'reservedTime', NULLIF(v_item ->> 'reservedTime', ''),
      'participants', v_participants,
      'options', v_options,
      'totalAmount', v_item_total
    ));
    v_total := v_total + v_item_total;
    v_item_count := v_item_count + 1;
    IF v_item_count = 1 THEN v_goods_name := v_product.name; END IF;
  END LOOP;

  v_order_id := 'ORD' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  INSERT INTO public.payment_orders(order_id, daycare_id, items, reserver_info, payment_method, amount)
  VALUES (v_order_id, v_daycare_id, v_snapshot, p_reserver_info, p_payment_method, v_total);
  RETURN jsonb_build_object(
    'orderId', v_order_id,
    'amount', v_total,
    'goodsName', CASE WHEN v_item_count > 1 THEN v_goods_name || ' 외 ' || (v_item_count - 1) || '건' ELSE v_goods_name END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.attach_signup_business_details()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_address text;
  v_address_detail text;
  v_zipcode text;
  v_category_text text;
  v_category_id uuid;
BEGIN
  IF COALESCE(NEW.raw_user_meta_data->>'account_type', '') <> 'business_owner_signup' THEN
    RETURN NEW;
  END IF;

  v_address := NULLIF(btrim(COALESCE(NEW.raw_user_meta_data->>'address', '')), '');
  v_address_detail := NULLIF(btrim(COALESCE(NEW.raw_user_meta_data->>'address_detail', '')), '');
  v_zipcode := NULLIF(regexp_replace(COALESCE(NEW.raw_user_meta_data->>'zipcode', ''), '[^0-9]', '', 'g'), '');
  v_category_text := btrim(COALESCE(NEW.raw_user_meta_data->>'category_id', ''));

  -- 구버전 클라이언트나 관리자 생성 계정은 새 메타데이터가 없을 수 있다.
  -- 계정 생성을 막지 않고, 두 값이 모두 유효한 신규 회원가입만 사업장에 동기화한다.
  IF v_address IS NULL
    OR v_category_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN
    RETURN NEW;
  END IF;

  v_category_id := v_category_text::uuid;
  IF NOT EXISTS (
    SELECT 1 FROM public.categories
    WHERE id = v_category_id AND is_active = true
  ) THEN
    RETURN NEW;
  END IF;

  UPDATE public.business_owner_signup_requests
  SET address = v_address,
      address_detail = v_address_detail,
      zipcode = v_zipcode,
      category_id = v_category_id,
      updated_at = now()
  WHERE auth_user_id = NEW.id;

  UPDATE public.business_owners
  SET address = v_address,
      address_detail = v_address_detail,
      zipcode = v_zipcode,
      updated_at = now()
  WHERE auth_user_id = NEW.id;

  UPDATE public.businesses
  SET address = v_address,
      address_detail = v_address_detail,
      zipcode = v_zipcode,
      category_id = v_category_id,
      updated_at = now()
  WHERE business_owner_id = NEW.id
    AND is_primary = true;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_daycare_safely(p_daycare_id uuid, p_confirmation_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_daycare public.daycares%ROWTYPE;
  v_admin_id uuid := auth.uid();
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admins
    WHERE id = v_admin_id AND is_active = true
  ) THEN
    RAISE EXCEPTION 'ADMIN_REQUIRED';
  END IF;

  SELECT * INTO v_daycare
  FROM public.daycares
  WHERE id = p_daycare_id
  FOR UPDATE;

  IF NOT FOUND OR v_daycare.status = 'deleted' THEN
    RAISE EXCEPTION 'DAYCARE_NOT_FOUND';
  END IF;

  IF btrim(coalesce(p_confirmation_name, '')) <> v_daycare.name THEN
    RAISE EXCEPTION 'CONFIRMATION_NAME_MISMATCH';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.business_owners
    WHERE auth_user_id = p_daycare_id
  ) THEN
    RAISE EXCEPTION 'SHARED_AUTH_ACCOUNT';
  END IF;

  UPDATE public.daycares
  SET status = 'deleted',
      deleted_at = now(),
      deleted_by = v_admin_id,
      updated_at = now()
  WHERE id = p_daycare_id;

  -- Removing the role blocks all role-gated APIs immediately. Removing the Auth user
  -- prevents future sign-in, while the daycare row remains as a historical reference.
  DELETE FROM public.user_roles WHERE id = p_daycare_id;
  DELETE FROM auth.users WHERE id = p_daycare_id;

  INSERT INTO public.admin_logs (
    admin_id,
    action,
    target_type,
    target_id,
    before_data
  ) VALUES (
    v_admin_id,
    'delete',
    'daycare',
    p_daycare_id,
    jsonb_build_object(
      'name', v_daycare.name,
      'email', v_daycare.email,
      'previous_status', v_daycare.status,
      'deletion_mode', 'soft_delete_with_auth_removal'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'daycare_id', p_daycare_id,
    'name', v_daycare.name
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.attach_signup_business_legal_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_legal_name text;
  v_business_name text;
BEGIN
  IF COALESCE(NEW.raw_user_meta_data->>'account_type', '') <> 'business_owner_signup' THEN
    RETURN NEW;
  END IF;

  v_legal_name := NULLIF(btrim(NEW.raw_user_meta_data->>'legal_name'), '');
  v_business_name := NULLIF(btrim(NEW.raw_user_meta_data->>'business_name'), '');
  IF v_legal_name IS NULL THEN
    RAISE EXCEPTION 'BUSINESS_SIGNUP_LEGAL_NAME_REQUIRED';
  END IF;
  IF v_business_name IS NULL THEN
    RAISE EXCEPTION 'BUSINESS_SIGNUP_BUSINESS_NAME_REQUIRED';
  END IF;
  IF length(v_legal_name) > 200 THEN
    RAISE EXCEPTION 'BUSINESS_SIGNUP_LEGAL_NAME_TOO_LONG';
  END IF;
  IF length(v_business_name) > 200 THEN
    RAISE EXCEPTION 'BUSINESS_SIGNUP_BUSINESS_NAME_TOO_LONG';
  END IF;

  UPDATE public.business_owner_signup_requests
  SET legal_name = v_legal_name, updated_at = now()
  WHERE auth_user_id = NEW.id;

  UPDATE public.business_owners
  SET legal_name = v_legal_name, updated_at = now()
  WHERE auth_user_id = NEW.id;

  UPDATE public.businesses b
  SET legal_name = v_legal_name, updated_at = now()
  FROM public.business_owners o
  WHERE b.business_owner_id = o.id
    AND o.auth_user_id = NEW.id
    AND b.is_primary = true;

  RETURN NEW;
END;
$function$
